#include <bits/stdc++.h>
using namespace std;

constexpr int MOD = 1'000'000'007;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t, l, r;
    cin >> t >> l >> r;

    vector<int> spf(r + 1);
    for (int i = 2; i <= r; ++i) {
        if (spf[i] == 0) {
            spf[i] = i;
            if (1LL * i * i <= r) {
                for (long long j = 1LL * i * i; j <= r; j += i) {
                    if (spf[j] == 0) spf[j] = i;
                }
            }
        }
    }

    vector<int> dp(r + 1);
    for (int i = 2; i <= r; ++i) {
        int p = spf[i];
        dp[i] = (dp[i / p] + 1LL * i * (p - 1) / 2) % MOD;
    }

    long long answer = 0;
    long long power = 1;
    for (int i = l; i <= r; ++i) {
        answer = (answer + power * dp[i]) % MOD;
        power = power * t % MOD;
    }

    cout << answer << '\n';
    return 0;
}

