#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    const int MOD = 1'000'000'007;

    long long t;
    int l, r;
    cin >> t >> l >> r;

    vector<int> spf(r + 1);
    vector<int> dp(r + 1);
    vector<int> primes;

    for (int i = 2; i <= r; ++i) {
        if (spf[i] == 0) {
            spf[i] = i;
            primes.push_back(i);
        }

        for (int p : primes) {
            if (p > spf[i] || 1LL * i * p > r) break;
            spf[i * p] = p;
        }

        long long cost = 1LL * i * (spf[i] - 1) / 2;
        dp[i] = (dp[i / spf[i]] + cost) % MOD;
    }

    long long answer = 0;
    long long power = 1;
    t %= MOD;

    for (int i = l; i <= r; ++i) {
        answer = (answer + power * dp[i]) % MOD;
        power = power * t % MOD;
    }

    cout << answer << '\n';
    return 0;
}

